if(($argv[1]??'')==='worker'){
 $p=json_decode(file_get_contents($argv[2]),true);$u=User::findOrFail($p['user']);auth()->setUser($u);file_put_contents($p['ready'],'ready');$deadline=microtime(true)+60;while(!file_exists($p['go'])){if(microtime(true)>$deadline)exit(2);usleep(10000);}$start=microtime(true);
 try{$a=app(LoanRequestService::class)->submit($u,$p['data']);$r=['outcome'=>'committed','activity'=>$a->id];}catch(ValidationException $e){$r=['outcome'=>'rejected','validation_fields'=>array_keys($e->errors())];}catch(Throwable $e){$r=['outcome'=>'error','class'=>get_class($e)];}$r['ms']=round((microtime(true)-$start)*1000,3);echo json_encode($r);exit;
