 for($i=0;$i<$count;$i++){$p=['user'=>$users[$i]->id,'data'=>$data($item,$quantity),'ready'=>$prefix.'-'.$i.'.ready','go'=>$prefix.'.go'];$file=$prefix.'-'.$i.'.json';file_put_contents($file,json_encode($p));$proc=proc_open([PHP_BINARY,__FILE__,'worker',$file],[1=>['pipe','w'],2=>['file',$prefix.'-'.$i.'.err','w']],$pipes);$workers[]=['proc'=>$proc,'pipe'=>$pipes[1],'ready'=>$p['ready']];}
 $deadline=microtime(true)+60;foreach($workers as $w){while(!file_exists($w['ready'])){if(microtime(true)>$deadline)throw new RuntimeException('Worker barrier timeout');usleep(10000);}}file_put_contents($prefix.'.go','release');$r=[];foreach($workers as $w){$r[]=json_decode(stream_get_contents($w['pipe']),true);fclose($w['pipe']);proc_close($w['proc']);}return$r;
