$rejected=false;try{$submit($users[3],$data($item,1,$date.' 09:30:00',$date.' 10:30:00'));}catch(ValidationException){$rejected=true;}$results[]=['id'=>'TIME-GENUINE-OVERLAP','expected'=>'reject capacity exceeded','actual'=>$rejected?'rejected':'accepted','pass'=>$rejected];
$item=$newItem('adjacent boundary',5);$submit($users[0],$data($item,3,$date.' 09:00:00',$date.' 10:00:00'));$submit($users[1],$data($item,3,$date.' 10:00:00',$date.' 11:00:00'));$peak=app(LoanAvailabilityService::class)->reservedItemQuantity($item->id,$date.' 09:00:00',$date.' 11:00:00');$results[]=['id'=>'TIME-ADJACENT','expected_peak'=>3,'actual_peak'=>$peak,'pass'=>$peak===3];
$item=$newItem('stale draft stock',5);auth()->setUser($users[0]);$draft=app(LoanRequestService::class)->saveDraft($users[0],$data($item,3));$submit($users[1],$data($item,3));auth()->setUser($users[0]);$rejected=false;try{app(LoanRequestService::class)->submitDraft($users[0],$draft);}catch(ValidationException){$rejected=true;}$results[]=['id'=>'DRAFT-STOCK-CHANGED','expected'=>'reject stale draft','actual'=>$rejected?'rejected':'accepted','pass'=>$rejected];
