$r=['scope'=>'real concurrent PHP services on isolated MySQL; not browser UAT or production load','mysql'=>DB::selectOne('select version() v')->v,'results'=>$results,'pass'=>!in_array(false,array_column($results,'pass'),true)];file_put_contents($root.'/docs/operational-readiness/evidence/2026-11-04/transaction-probes.json',json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));echo json_encode($r,JSON_PRETTY_PRINT).PHP_EOL;exit($r['pass']?0:1);
